def compute_magnitude_scores(model):
    config = model.config
    n_layers = config.num_hidden_layers
    n_heads = config.num_attention_heads
    n_kv_heads = config.num_key_value_heads
    head_dim = config.hidden_size // n_heads
    heads_per_kv = n_heads // n_kv_heads
    intermediate_size = config.intermediate_size
    n_mlp_groups = n_heads
    mlp_group_size = intermediate_size // n_mlp_groups

    attn_scores = {}
    mlp_scores = {}

    for layer_idx in range(n_layers):
        layer = model.model.layers[layer_idx]
        attn = layer.self_attn
        mlp = layer.mlp

        group_mags = []
        for g in range(n_kv_heads):
            mag = 0.0
            for qh in range(heads_per_kv):
                h = g * heads_per_kv + qh
                q_slice = attn.q_proj.weight.data[h*head_dim:(h+1)*head_dim, :]
                mag += q_slice.float().norm().item() ** 2
                o_slice = attn.o_proj.weight.data[:, h*head_dim:(h+1)*head_dim]
                mag += o_slice.float().norm().item() ** 2
            k_slice = attn.k_proj.weight.data[g*head_dim:(g+1)*head_dim, :]
            mag += k_slice.float().norm().item() ** 2
            v_slice = attn.v_proj.weight.data[g*head_dim:(g+1)*head_dim, :]
            mag += v_slice.float().norm().item() ** 2
            group_mags.append(mag ** 0.5)
        attn_scores[layer_idx] = torch.tensor(group_mags)

        mlp_mags = []
        for g in range(n_mlp_groups):
            start = g * mlp_group_size
            end = start + mlp_group_size
            mag = 0.0
            mag += mlp.gate_proj.weight.data[start:end, :].float().norm().item() ** 2
            mag += mlp.up_proj.weight.data[start:end, :].float().norm().item() ** 2
            mag += mlp.down_proj.weight.data[:, start:end].float().norm().item() ** 2
            mlp_mags.append(mag ** 0.5)
        mlp_scores[layer_idx] = torch.tensor(mlp_mags)

    return attn_scores, mlp_scores


'''

